-- Passage rg12-story-details-inference-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('00982fa1-3251-5590-803f-299382e8b1d7', 'rg12-story-details-inference-p05', (select id from public.skills where slug = 'read-g12-story-details-inference'), null,
        '9-12', $q$Count$q$, $q$The survey sheet asked for honest numbers,
so I lay on the cold hood of the car
with a clipboard on my chest
and a red flashlight that showed my pencil and nothing else.
My job was simple: one hour, one patch of sky,
a tally mark for every streak of light I saw.

The first ten minutes gave me nothing.
Then three came at once, low in the east,
and I almost wrote four because I wanted to.
I did not.
Somewhere a scientist I would never meet
was going to add my marks to thousands of others,
and a guess, I thought, would hide inside the total
like a pebble in a shoe.

At half past one the clouds arrived,
slow and gray, covering my patch first.
The form had a box for that, too:
percent of field obscured.
I wrote forty, then erased it and wrote fifty,
because the edge of the cloud kept moving
and fifty felt closer to the truth.

I finished with nineteen marks.
My cousin, two cars down, had counted thirty-one
and asked how I could have missed so many.
I told her I had only counted what I saw.
She shrugged, but I noticed later
she had crossed out one of her own.$q$, 'draft')
