  ('7a944b59-0eba-53a1-b645-6b52d48ae1fa', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'medium',
   $q$How does the opening description of the scoring machine help develop the theme?$q$, $q$[{"text":"It explains that Marisol lost because the machine counted touches that never landed.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"It suggests that Freya tampered with the cables to win her bout.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that the tournament organizers were careless and should be blamed for the loss.","is_correct":false,"misconception_token":"includes-opinion"},{"text":"It establishes that the machine cannot be trusted, so the honest call depends entirely on Marisol.","is_correct":true}]$q$::jsonb, $q$It establishes that the machine cannot be trusted, so the honest call depends entirely on Marisol.$q$, $q$Because the machine has already failed, no one else can know the touch landed, which makes Marisol's choice a true test of integrity. Nothing suggests Freya tampered with anything.$q$, 'draft', '66abf76b-c2d5-521f-bd75-08325eac49d5')
