  ('9235b8aa-d897-5848-8626-12738ea54dad', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'medium',
   $q$What is the significance of the line "My grandmother does not drive anymore, so I drove her"?$q$, $q$[{"text":"It reveals that the speaker has just learned to drive and is proud of it.","is_correct":false,"misconception_token":"too-narrow"},{"text":"It suggests that the speaker is reluctant and only drives because of obligation.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"It shows the roles reversing as the speaker takes on the guiding role, echoing the young cranes learning the route.","is_correct":true},{"text":"It shows that the grandmother is too ill to enjoy the trip to the river.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows the roles reversing as the speaker takes on the guiding role, echoing the young cranes learning the route.$q$, $q$The driver changes from grandmother to speaker, showing the tradition passing to the next generation just as young cranes "learn the way by flying it." Nothing suggests illness or reluctance.$q$, 'draft', 'b5945d61-2ba0-5c29-8d89-fade7d73d655')
