  ('5be4c418-1056-5146-ae4f-01da519bfa0a', null, (select id from public.skills where slug = 'read-g12-word-parts'), null, 'easy',
   $q$The root equi means "equal." What does it mean that the crew was "equidistant" from the start and the finish?$q$, $q$[{"text":"The crew was the same distance from both points","is_correct":true},{"text":"The crew was moving at an equal speed throughout","is_correct":false,"misconception_token":"confuses-distance-speed"},{"text":"The crew was much closer to the finish line","is_correct":false,"misconception_token":"ignores-root-clues"},{"text":"The crew was level with the rival boat","is_correct":false,"misconception_token":"context-only-guess"}]$q$::jsonb, $q$The crew was the same distance from both points$q$, $q$Equi plus distant means equally far, and the passage places this "halfway through" with "the next mile and a half" still ahead. Equal speed misreads the word, which is about distance, not pace.$q$, 'draft', 'd0ad9405-d926-5787-b2f2-fa201e805e69')
