-- Passage wg3-opinion-writing-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('6112fea3-6c76-5bb0-8a73-9a6bcd2a9b59', 'wg3-opinion-writing-p01', (select id from public.skills where slug = 'write-g3-opinion-writing'), null,
        '3-5', $q$A Fish Tank for Room 12$q$, $q$(1) Our classroom should get a fish tank. (2) A fish tank would help us learn about science. (3) We could watch the fish eat, swim and grow every day. (4) We could also write down what we see in a science journal.

(5) Taking care of fish would teach us to be responsible. (6) Each week, two students could feed the fish and check the water. (7) My cousin has a pet hamster named Biscuit.

(8) Fish are also calm and quiet, so they would not bother anyone during lessons. (9) Watching them swim might even help us relax before a test.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
